    "title": "2026物理诺奖时隔34年一人独揽，他把一立方千米的南极冰变成了望远镜",
    "link": "https://m.thepaper.cn/detail/34206945",
    "pub_date": "2026-10-07 09:09:05",
    "author": "",
    "description": "2026年诺贝尔物理学奖授予美国理论物理学家弗朗西斯·哈尔岑（Francis Halzen），以表彰他对冰立方（IceCube）中微子天文台的杰出贡献，以及对源自天体的高能中微子的发现。 这是诺贝尔物理学奖历史上第五次嘉奖中微子研究，也是继1992年之后，时隔34年再次因中微子研究授予单一获奖者。此前四次中微子相关诺奖分别为：1988年因发现μ子中微子，1995年因首次实验探测中微子，2002年因关于宇宙中微子和太阳中微子探测，以及20…",
    "content": "2026年诺贝尔物理学奖授予美国理论物理学家弗朗西斯·哈尔岑（Francis Halzen），以表彰他对冰立方（IceCube）中微子天文台的杰出贡献，以及对源自天体的高能中微子的发现。 这是诺贝尔物理学奖历史上第五次嘉奖中微子研究，也是继1992年之后，时隔34年再次因中微子研究授予单一获奖者。此前四次中微子相关诺奖分别为：1988年因发现μ子中微子，1995年因首次实验探测中微子，2002年因关于宇宙中微子和太阳中微子探测，以及2015年因发现中微子振荡。 与此前几次主要聚焦中微子本身的性质和基本粒子物理不同，…"
