    "content": "文/路柯 短视频平台上的AI博主们，正在越来越卷，一拨人新模型、新工具的测评频率在加速，而另一拨人，迈入AI创作领域的，也在向影视创作的专业标准靠拢。 这轮竞争中，影视科班的存在感尤为强烈。 9月收官的抖音AI创作大赛，金奖由“2XLabs”的《合龙》摘得，这支团队有十余年影视行业经验。银奖作品《反正也没时间活》的作者“站立起来的影子”，此前从事过导演、摄影、编剧和灯光工作，还曾进入院校教授摄影与影视课程。 抖音截图 B站的“DiDi_OK”同样如此。 他是动画专业出身，曾在伦敦广告巨头WPP集团从事广告与视觉工作…"
