    "description": "“2025年云南省从事旅居业务的自然村达到了824个，较2024年增长15倍，直接盘活农村闲置房屋2.74万余间。” 文 /巴九灵（微信公众号：吴晓波频道） 请3休13，今年国庆和中秋，凑出了一个难得的长假。 有人把时间花在路上，大兴安岭、青甘大环线、川西依然是热门目的地；有人请假飞往国外；有人把假期拆开来用，旅行和休息各占一部分。 但还有一群人，开始换一种方式过长假：找一个喜欢的地方，住上一两周，自己买菜、做饭，慢慢过几天当地人的生活…",
    "content": "“2025年云南省从事旅居业务的自然村达到了824个，较2024年增长15倍，直接盘活农村闲置房屋2.74万余间。” 文 /巴九灵（微信公众号：吴晓波频道） 请3休13，今年国庆和中秋，凑出了一个难得的长假。 有人把时间花在路上，大兴安岭、青甘大环线、川西依然是热门目的地；有人请假飞往国外；有人把假期拆开来用，旅行和休息各占一部分。 但还有一群人，开始换一种方式过长假：找一个喜欢的地方，住上一两周，自己买菜、做饭，慢慢过几天当地人的生活。 张彬最近就遇到了这样的客人。他是遵义市正安县庙塘镇板房村人，在村里开了一家旅…"
