    "description": "近日，“青海祁连县让游客免费住学生宿舍”的话题冲上了热搜。舆论场上，不同的人从不同的角度出发，对此做出了不同的评判。 据中央广播电视台总台报道，国庆假期，青海祁连县这座常住人口仅5万的小城，单日涌入游客超10万人，瞬时客流彻底超出县域旅游承载能力。为此，当地文旅部门迅速启动应急预案，连夜开放学校宿舍作为公益床位安置滞留游客。 对于当地这一举措，有人认为，紧急时刻盘活闲置资源、保障游客安全，是负责任、有温度的政务服务，给当地加分了。但也有…",
    "content": "近日，“青海祁连县让游客免费住学生宿舍”的话题冲上了热搜。舆论场上，不同的人从不同的角度出发，对此做出了不同的评判。 据中央广播电视台总台报道，国庆假期，青海祁连县这座常住人口仅5万的小城，单日涌入游客超10万人，瞬时客流彻底超出县域旅游承载能力。为此，当地文旅部门迅速启动应急预案，连夜开放学校宿舍作为公益床位安置滞留游客。 对于当地这一举措，有人认为，紧急时刻盘活闲置资源、保障游客安全，是负责任、有温度的政务服务，给当地加分了。但也有人追问，如此征用学生宿舍，公权力能不能擅自决定？学生和家长有没有、应不应该知情？…"
