    "description": "2026年10月07日 周 涛摄（人民视觉） \"> 从河南郑州市一路向南，扎进大别山，穿过片片茶园，来到信阳市罗山县铁铺镇何家冲村。一棵古银杏，树冠如伞，护着四方土地。 1934年11月16日，红二十五军近3000人集结于此，誓师出征。历时10个月，转战豫、鄂、陕、甘多地，最终到达陕北。 “这一路山高路险，缺衣少药是红军常态。多亏了有三株‘草’——茶叶提神，油茶果充饥，连翘清热解毒。”罗山县文化广电和旅游局讲解员许清说，“这三株‘草’，…",
    "content": "2026年10月07日 红二十五军长征出发地——河南罗山县何家冲。 周 涛摄（人民视觉） \"> 从河南郑州市一路向南，扎进大别山，穿过片片茶园，来到信阳市罗山县铁铺镇何家冲村。一棵古银杏，树冠如伞，护着四方土地。 1934年11月16日，红二十五军近3000人集结于此，誓师出征。历时10个月，转战豫、鄂、陕、甘多地，最终到达陕北。 “这一路山高路险，缺衣少药是红军常态。多亏了有三株‘草’——茶叶提神，油茶果充饥，连翘清热解毒。”罗山县文化广电和旅游局讲解员许清说，“这三株‘草’，是沿途百姓能够拿出来的最朴素也是最金…"
