    "author": "",
    "description": "2026年10月07日 四川成都，天府锦城实验室。冷冻电镜下，生物大分子结构轮廓纤毫毕现。 “早些年做这样的冷冻电镜实验得排长队，拿着样本去省外借仪器。”实验室冷冻电镜平台科学家邵振华回忆，当时设备稀缺，时间紧张，出一趟差往往只够跑几组数据。 如今，校地合作、协同发力——成都市与四川大学共建天府锦城实验室，围绕恶性肿瘤、心脑血管与代谢等方向开展研究。“实验室已建成中西部地区规模最大、设备最先进、开放共享的冷冻电镜平台之一，科研效率大幅提…",
    "content": "2026年10月07日 四川成都，天府锦城实验室。冷冻电镜下，生物大分子结构轮廓纤毫毕现。 “早些年做这样的冷冻电镜实验得排长队，拿着样本去省外借仪器。”实验室冷冻电镜平台科学家邵振华回忆，当时设备稀缺，时间紧张，出一趟差往往只够跑几组数据。 如今，校地合作、协同发力——成都市与四川大学共建天府锦城实验室，围绕恶性肿瘤、心脑血管与代谢等方向开展研究。“实验室已建成中西部地区规模最大、设备最先进、开放共享的冷冻电镜平台之一，科研效率大幅提升。”邵振华说，“我们将以习近平总书记给四川大学全体师生重要回信精神为指引，发挥…"
