    "author": "",
    "description": "2026年10月07日 本报记者 范昊天摄 \"> 金秋时节，鄂皖交界，走进湖北黄冈市英山县陶家河乡英太寨村，背靠大山的一座农家院里，68岁的陈世国拿出了她的“传家宝”。 轻轻打开木匣子，巴掌大小的小木雀映入眼帘，历经岁月洗礼，外形依然灵动。这只小木雀背后，藏着一段大别山军民同心、生死相护的往事。 1934年的秋天，在红四方面军撤离后一直坚守鄂豫皖苏区的红二十五军移驻陶家河。在这里，他们发布《告劳苦群众书》、建立苏维埃政权、开展土地革命、…",
    "content": "2026年10月07日 图为陈世国老人展示小木雀。 本报记者 范昊天摄 \"> 金秋时节，鄂皖交界，走进湖北黄冈市英山县陶家河乡英太寨村，背靠大山的一座农家院里，68岁的陈世国拿出了她的“传家宝”。 轻轻打开木匣子，巴掌大小的小木雀映入眼帘，历经岁月洗礼，外形依然灵动。这只小木雀背后，藏着一段大别山军民同心、生死相护的往事。 1934年的秋天，在红四方面军撤离后一直坚守鄂豫皖苏区的红二十五军移驻陶家河。在这里，他们发布《告劳苦群众书》、建立苏维埃政权、开展土地革命、进行系统训练，为长征做好了政治、组织、军事、思想上的…"
