    "description": "2026年10月07日 走进湖北省博物馆曾侯乙展厅，一套恢弘大气的青铜编钟陈列其中。湖北省博物馆馆标采用曾侯乙编钟造型，展现礼乐文明源远流长、荆楚文化绵延不绝。 记者：在众多馆藏国宝之中，为何选定曾侯乙编钟作为湖北省博物馆的馆标原型？ 张晓云：曾侯乙编钟（见图，任勇摄）1978年出土于湖北随县的曾侯乙墓，这套编钟是迄今发现的规模最大、保存最完好的一组编钟，记录了2400多年前中国古代的音乐实践和音乐理论。1988年11月，为总结曾侯乙编…",
    "content": "2026年10月07日 走进湖北省博物馆曾侯乙展厅，一套恢弘大气的青铜编钟陈列其中。湖北省博物馆馆标采用曾侯乙编钟造型，展现礼乐文明源远流长、荆楚文化绵延不绝。 记者：在众多馆藏国宝之中，为何选定曾侯乙编钟作为湖北省博物馆的馆标原型？ 张晓云：曾侯乙编钟（见图，任勇摄）1978年出土于湖北随县的曾侯乙墓，这套编钟是迄今发现的规模最大、保存最完好的一组编钟，记录了2400多年前中国古代的音乐实践和音乐理论。1988年11月，为总结曾侯乙编钟研究成果，弘扬中华文化，促进中外文化交流，湖北省对外文化交流协会、湖北省博物馆…"
