    "description": "2026年10月07日 李贤杰摄 \"> “延吉不大，但有着满满的民族味儿和烟火气。”在吉林省延边朝鲜族自治州延吉市文旅推介官厉成根看来，延吉的朝鲜族民俗文化和特色饮食，共同构成这座城市别样的风景。 今年盛夏，中国朝鲜族民俗园等多个景区业态焕新，“东北超”等体育赛事、非遗演艺、夜间经济等文旅项目接连推出，与美食佳肴、文旅景点相互融合。走进中国朝鲜族民俗园，首先映入眼帘的是飞檐翘角、青瓦白墙的传统民居。在这里，游客既能租赁朝鲜族服饰旅拍，还…",
