    "description": "82岁的弗朗西斯·哈尔岑（Francis Halzen），虽然早过了退休年龄，但只要得空，便会待在他位于威斯康辛大学麦迪逊分校的办公室里。他的办公室门总是敞开着，随时欢迎任何人来找他；只有开会时，那扇门才会关上。 10月6日，2026年诺贝尔物理学奖授予比利时裔美国物理学家弗朗西斯·哈尔岑，表彰他对冰立方中微子天文台（IceCube Neutrino Observatory）的决定性贡献以及发现源自天体的高能中微子。这是近半个世纪极为罕…",
    "content": "82岁的弗朗西斯·哈尔岑（Francis Halzen），虽然早过了退休年龄，但只要得空，便会待在他位于威斯康辛大学麦迪逊分校的办公室里。他的办公室门总是敞开着，随时欢迎任何人来找他；只有开会时，那扇门才会关上。 10月6日，2026年诺贝尔物理学奖授予比利时裔美国物理学家弗朗西斯·哈尔岑，表彰他对冰立方中微子天文台（IceCube Neutrino Observatory）的决定性贡献以及发现源自天体的高能中微子。这是近半个世纪极为罕见的单人独享物理学诺奖，上一次物理学家独享还要追溯到1992年。 历经数十年攻坚…"
