    "author": "高山",
    "description": "新华社洛杉矶10月6日电（记者高山）经过数月的竞购角逐以及法律拉锯战，派拉蒙天舞公司6日宣布完成对华纳兄弟探索公司价值约1100亿美元的收购，打造出一家横跨好莱坞和新闻行业的全新超级传媒集团。这是美国传媒行业历史上规模最大的并购交易之一。 这家新公司将简称为天舞。旗下将包括派拉蒙和华纳兄弟的电影及电视制片厂、Paramount+和HBO Max等流媒体服务，以及美国有线电视新闻网和哥伦比亚广播公司新闻部两大新闻机构。美科技巨头甲骨文创始…",
