    "content": "新华社联合国10月6日电 中国常驻联合国代表傅聪6日在“联合国同非洲联盟合作”安理会公开会上发言，敦促国际社会持续助力非洲国家的和平与发展。 傅聪说，非洲正成为具有全球影响的重要一极。联合国和非盟伙伴关系是多边合作的典范，为促进非洲和平、稳定与发展发挥了重要作用。当前，国际形势变乱交织，地缘冲突延宕不止、发展鸿沟持续扩大、全球性挑战层出不穷。非洲国家在实现“消弭枪声”、探索符合自身国情的现代化道路方面，需要联合国及国际社会的持续支持。他就此提出三点主张。 第一，政治解决热点问题，共促非洲和平稳定。国际社会应支持以非…"
