    "description": "新华社贝鲁特10月6日电（记者申峰）黎巴嫩真主党领导人纳伊姆·卡西姆6日表示，只要以色列军队仍驻留在黎境内，真主党就将继续“抵抗”，以军撤出黎巴嫩是解决冲突的前提。 据黎巴嫩国家通讯社报道，卡西姆当天在一场活动上发表讲话说，以军撤出黎巴嫩是解决冲突的必要条件，并称以色列在该地区的行动得到美国支持。 在谈及黎巴嫩国内问题时，卡西姆表示，真主党愿就武器、经济、就业等问题开展合作，但相关合作必须在黎巴嫩宪法和法律框架内进行，“不接受美国或其他…",
    "content": "新华社贝鲁特10月6日电（记者申峰）黎巴嫩真主党领导人纳伊姆·卡西姆6日表示，只要以色列军队仍驻留在黎境内，真主党就将继续“抵抗”，以军撤出黎巴嫩是解决冲突的前提。 据黎巴嫩国家通讯社报道，卡西姆当天在一场活动上发表讲话说，以军撤出黎巴嫩是解决冲突的必要条件，并称以色列在该地区的行动得到美国支持。 在谈及黎巴嫩国内问题时，卡西姆表示，真主党愿就武器、经济、就业等问题开展合作，但相关合作必须在黎巴嫩宪法和法律框架内进行，“不接受美国或其他外部势力的指示”。 黎巴嫩、以色列和美国三方6月26日在美国华盛顿完成谈判后，宣…"
