    "description": "新华社布宜诺斯艾利斯10月6日电（记者张铎）阿根廷外长巴勃罗·基尔诺5日晚批评英国政府在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）主权争端中拒绝谈判。 基尔诺5日晚在阿根廷国际关系委员会成立48周年纪念活动上重申阿政府对马岛的主权，并批评英国政府的单方面行为“损害了阿根廷的不可再生资源”。英国驻阿根廷大使戴维·凯恩斯在基尔诺发言后离开活动现场。 基尔诺在讲话中还敲打智利政府不要在马岛主权争端上与英国政府合作。他强调，阿根廷尊重他国的基…",
    "content": "新华社布宜诺斯艾利斯10月6日电（记者张铎）阿根廷外长巴勃罗·基尔诺5日晚批评英国政府在马尔维纳斯群岛（简称马岛，英国称福克兰群岛）主权争端中拒绝谈判。 基尔诺5日晚在阿根廷国际关系委员会成立48周年纪念活动上重申阿政府对马岛的主权，并批评英国政府的单方面行为“损害了阿根廷的不可再生资源”。英国驻阿根廷大使戴维·凯恩斯在基尔诺发言后离开活动现场。 基尔诺在讲话中还敲打智利政府不要在马岛主权争端上与英国政府合作。他强调，阿根廷尊重他国的基本利益并希望得到同样的尊重，他国言行将决定双边关系的深度。9月底，一架隶属于英国…"
