    "content": "新华社东京10月6日电（记者梁晨 李子越）据日本共同社6日报道，在一名驻冲绳美军士兵因涉嫌抢劫杀人被捕后，驻冲绳美军最高负责人、冲绳地区协调官沃森6日下令，自9日起对所有驻冲绳美军人员实施为期30天的外出限制，每日零时至凌晨5时禁止外出。 报道说，驻冲绳美军还将于7日中午至9日中午暂停日常勤务。在此期间，军人不得在非执勤时间到基地外活动，在基地内外均不得饮酒。 日本冲绳县警方4日逮捕了美国士兵德文·巴拉德。巴拉德现年20岁，隶属驻扎在美军普天间基地的美国海军陆战队。他涉嫌于当地时间3日凌晨在冲绳县那霸市一家酒店杀害…"
