    "content": "新华社纽约10月6日电（记者刘亚南）美国商务部6日发布的数据显示，受进口显著增加影响，美国8月商品和服务贸易逆差环比增加13.7%，升至1056亿美元。 数据显示，美国8月商品与服务出口额为3152亿美元，环比增加1.4%；进口额环比增加4.3%至4208亿美元。 数据还显示，美国8月商品出口和进口分别增加44亿美元和172亿美元。其中，工业原材料和资本货物出口分别增加63亿美元和13亿美元，消费品出口则下降22亿美元。工业原材料和资本货物进口分别增加91亿美元和62亿美元，资本货物1464亿美元的进口额为有记录以…"
