    "author": "谷训",
    "description": "10月6日，中国队球员刘洋（右一）与塔吉克斯坦队球员塔布雷兹·伊斯洛莫夫在比赛中拼抢。新华社记者 黄伟 摄 新华社重庆10月6日电（记者谷训）在6日晚进行的2026CFA中国之队·重庆国际足球邀请赛中，中国男足0:1负于塔吉克斯坦队。 上半场双方均无建树。第53分钟，塔吉克斯坦队在外围完成一脚远射，射门角度较正，中国队门将刘殿座在接球时出现脱手，未能将球控制住。对方球员哈诺诺夫迅速跟进，门前补射破门，塔吉克斯坦队1:0领先。 10月6日…",
    "content": "10月6日，中国队球员刘洋（右一）与塔吉克斯坦队球员塔布雷兹·伊斯洛莫夫在比赛中拼抢。新华社记者 黄伟 摄 新华社重庆10月6日电（记者谷训）在6日晚进行的2026CFA中国之队·重庆国际足球邀请赛中，中国男足0:1负于塔吉克斯坦队。 上半场双方均无建树。第53分钟，塔吉克斯坦队在外围完成一脚远射，射门角度较正，中国队门将刘殿座在接球时出现脱手，未能将球控制住。对方球员哈诺诺夫迅速跟进，门前补射破门，塔吉克斯坦队1:0领先。 10月6日，主裁判崔贤宰（左一）向中国队球员韦世豪（右一）出示红牌。新华社记者 黄伟 摄 …"
