    "content": "新华社斯德哥尔摩10月6日电（记者郭爽 朱昊晨 张馨文）穿过我们的身体，甚至穿过整个地球，“宇宙中最害羞的粒子”——中微子通常不留痕迹。不过，在南极深冰下，来自遥远宇宙的高能中微子偶尔也会因与原子核的碰撞而激起微光。这些微光由埋在冰中的探测器记录下，我们就可能读到“宇宙来信”。 为接收这样的“来信”，2026年诺贝尔物理学奖得主弗朗西斯·哈尔岑和同行，把1立方千米南极深冰变成了一座特殊“邮箱”——冰立方中微子天文台。 这是10月6日在瑞典斯德哥尔摩拍摄的2026年诺贝尔物理学奖公布现场。新华社记者吕优摄 “悄无声息…"
