    "author": "朱昊晨,张馨文,郭爽",
    "description": "瑞典皇家科学院6日宣布，将2026年诺贝尔物理学奖授予科学家弗朗西斯·哈尔岑，以表彰其对冰立方中微子天文台的决定性贡献和发现具有天体物理起源的高能中微子。 请听诺贝尔物理学委员会委员、瑞典乌普萨拉大学教授奥勒·埃里克松揭秘：今年物理学奖为何只颁给单个科学家？中微子是啥？为何难探测？（记者：邓驰旻、朱昊晨、张馨文、郭爽；视频：史晨渲）",
    "content": "瑞典皇家科学院6日宣布，将2026年诺贝尔物理学奖授予科学家弗朗西斯·哈尔岑，以表彰其对冰立方中微子天文台的决定性贡献和发现具有天体物理起源的高能中微子。 请听诺贝尔物理学委员会委员、瑞典乌普萨拉大学教授奥勒·埃里克松揭秘：今年物理学奖为何只颁给单个科学家？中微子是啥？为何难探测？（记者：邓驰旻、朱昊晨、张馨文、郭爽；视频：史晨渲）"
