    "content": "新华社香港10月6日电（刘英伦、郭辛）香港入境事务处6日公布，皇岗口岸将采用“合作查验、一次放行”通关模式，旅客使用“合作查验”自助通道时，只需排队一次及出示一次证件，便可完成港深两地出入境手续。 香港入境处介绍，重建后的皇岗口岸设有134条“合作查验”自助通道和68个传统人工柜台。使用自助通道办理出入境手续时间仅需约20秒。 香港入境处表示，使用“合作查验”自助通道须提前登记，共有四种登记方式。其中，香港居民和持有往来港澳通行证并附有有效访港签注的内地访客都可以使用的有两种。合资格通关旅客可前往皇岗口岸的e-道登…"
