    "description": "新华社香港10月6日电（记者舒娜）“中国内地电影展2026”6日在香港大会堂举行开幕典礼，选映12部内地电影，展现内地影坛创作潜能，推动内地与香港文化交流。 香港特区政府文化体育及旅游局副局长刘震在致辞中表示，电影作为富有感染力的大众艺术，是讲好中国故事、传承中华文化、促进民心相通的重要载体。特区政府将积极发挥桥梁作用，持续推动内地与香港的文化交流互鉴。 他说，“中国内地电影展”多年来深耕两地电影交流，既是香港观众认识内地影坛最新发展的…",
    "content": "新华社香港10月6日电（记者舒娜）“中国内地电影展2026”6日在香港大会堂举行开幕典礼，选映12部内地电影，展现内地影坛创作潜能，推动内地与香港文化交流。 香港特区政府文化体育及旅游局副局长刘震在致辞中表示，电影作为富有感染力的大众艺术，是讲好中国故事、传承中华文化、促进民心相通的重要载体。特区政府将积极发挥桥梁作用，持续推动内地与香港的文化交流互鉴。 他说，“中国内地电影展”多年来深耕两地电影交流，既是香港观众认识内地影坛最新发展的重要窗口，也是两地业界交流创作、分享经验、协作共进的专业平台，通过光影凝聚共鸣、…"
