    "author": "张毅荣,李超",
    "description": "新华社柏林10月6日电（记者张毅荣 李超）德国萨克森-安哈尔特州（萨安州）议会6日选举极右翼德国选择党议员托比亚斯·劳施为议长。这是德国首次由选择党成员担任联邦州议会议长。 当天，萨安州新一届议会在州首府马格德堡举行首次会议。35岁的劳施在首轮投票中获得48张赞成票，另有29票反对、5票弃权。 据德媒报道，当天数百名抗议者聚集在州议会大厦前，反对劳施出任州议会议长。 选择党在9月6日举行的该州议会选举中获得43.8%的选票，成为该州第一…",
    "content": "新华社柏林10月6日电（记者张毅荣 李超）德国萨克森-安哈尔特州（萨安州）议会6日选举极右翼德国选择党议员托比亚斯·劳施为议长。这是德国首次由选择党成员担任联邦州议会议长。 当天，萨安州新一届议会在州首府马格德堡举行首次会议。35岁的劳施在首轮投票中获得48张赞成票，另有29票反对、5票弃权。 据德媒报道，当天数百名抗议者聚集在州议会大厦前，反对劳施出任州议会议长。 选择党在9月6日举行的该州议会选举中获得43.8%的选票，成为该州第一大党，但未获得绝对多数席位。莎拉·瓦根克内希特联盟此前表示，将支持劳施出任议长，…"
