    "title": "学习原声丨以文化滋养精神家园",
    "link": "http://www.news.cn/20261006/47acdeea8d0f473f8b29c611de68d26f/c.html",
    "pub_date": "2026-10-06 22:15:22",
    "author": "",
    "description": "\"2023年10月，全国宣传思想文化工作会议正式提出习近平文化思想。\" 文化兴国运兴，文化强民族强。2023年10月，全国宣传思想文化工作会议正式提出习近平文化思想。习近平文化思想是新时代党领导文化建设实践经验的理论总结，丰富和发展了马克思主义文化理论，构成了习近平新时代中国特色社会主义思想的文化篇。 统筹：吴炜玲、张紫赟 编导：杨慕茜 记者：金剑 海报：刘旭峰 新华社音视频部制作",
    "content": "\"2023年10月，全国宣传思想文化工作会议正式提出习近平文化思想。\" 文化兴国运兴，文化强民族强。2023年10月，全国宣传思想文化工作会议正式提出习近平文化思想。习近平文化思想是新时代党领导文化建设实践经验的理论总结，丰富和发展了马克思主义文化理论，构成了习近平新时代中国特色社会主义思想的文化篇。 统筹：吴炜玲、张紫赟 编导：杨慕茜 记者：金剑 海报：刘旭峰 新华社音视频部制作"
