    "content": "新华社科威特城10月6日电（记者尹炣）萨那消息：也门胡塞武装军事发言人叶海亚·萨雷亚6日在社交媒体发表声明称，胡塞武装当天在也门南部拉赫季省对“沙特支持的武装人员集结地”发动数十次袭击，造成对方200多人伤亡。 声明说，这一伤亡规模在近期交战中“前所未有”。胡塞武装还袭击了也门北部焦夫省东部以及邻近产油省马里卜省东部的“沙特支持的武装人员集结地”。 声明还说，有关政府军在也门西海岸大范围推进的报道有所夸大。胡塞武装正在西南部塔伊兹省继续对政府军展开军事行动。 萨雷亚当天还公布了视频画面，显示胡塞武装使用无人机和导弹…"
