    "description": "中国婚恋市场的核心问题，不是“总量”问题，而是“结构”问题。 李井奎 责任编辑：顾策 2020年，人口学家和经济学家中流传着一张特殊的“中国地图”，但它标示的不是GDP，也不是人口密度，而是用红色和蓝色分别标出中国各个地级市的“单身率性别差”。红色的区域表示男性单身率高于女性，蓝色的区域表示女性单身率高于男性。 在这张地图上，云南、贵州、甘肃等欠发达内陆地区，是一片深红；而长三角、珠三角、京津冀等发达城市群，则是一片深蓝。红蓝分界线，几…",
    "content": "中国婚恋市场的核心问题，不是“总量”问题，而是“结构”问题。 李井奎 责任编辑：顾策 2020年，人口学家和经济学家中流传着一张特殊的“中国地图”，但它标示的不是GDP，也不是人口密度，而是用红色和蓝色分别标出中国各个地级市的“单身率性别差”。红色的区域表示男性单身率高于女性，蓝色的区域表示女性单身率高于男性。 在这张地图上，云南、贵州、甘肃等欠发达内陆地区，是一片深红；而长三角、珠三角、京津冀等发达城市群，则是一片深蓝。红蓝分界线，几乎就是中国经济发展水平的分界线。这意味着，在欠发达地区，找不到老婆的男性更多；在…"
