    "author": "温馨,吴光于",
    "description": "岷江汤汤，穿山奔涌而来，在四川盆地边缘与拥有2000多年历史的都江堰相遇，湍急江水化作汩汩清流，润泽成都平原，孕育“天府粮仓”。 2025年12月5日，习近平总书记在成都市都江堰同法国总统马克龙进行友好交流。论及文化自信与国家强盛、民族复兴的关系，总书记强调，“有文化自信的民族，才能立得住、站得稳、行得远”，折射出对中华文明传承发展的深邃思考。 作为全世界迄今唯一仍在使用的古代水利工程，都江堰是人类与自然和谐共生最早的成功实践之一。“深…",
    "content": "岷江汤汤，穿山奔涌而来，在四川盆地边缘与拥有2000多年历史的都江堰相遇，湍急江水化作汩汩清流，润泽成都平原，孕育“天府粮仓”。 2025年12月5日，习近平总书记在成都市都江堰同法国总统马克龙进行友好交流。论及文化自信与国家强盛、民族复兴的关系，总书记强调，“有文化自信的民族，才能立得住、站得稳、行得远”，折射出对中华文明传承发展的深邃思考。 作为全世界迄今唯一仍在使用的古代水利工程，都江堰是人类与自然和谐共生最早的成功实践之一。“深淘滩、低作堰”，刻在二王庙石壁上的治水“六字诀”至今清晰可见，它与“乘势利导、因…"
