    "author": "陈爱平",
    "description": "新华社上海10月6日电（记者陈爱平）这个国庆节假期，上海白领郑冰的安排既充实又从容。她和朋友们在中秋节假期出发、前往马来西亚海边潜水、冲浪，国庆节假期后半段回到上海后，她们打卡了徐汇西岸融合网球与音乐的“ACE汇师”城市主题活动，又到辰山植物园露营放松。 重庆游客陈奕一家前往法国、西班牙自由行，他们整个行程有13天，在巴黎、巴塞罗那专门留出了充裕时间去逛博物馆、公园等。“此次安排舒缓而有深度，一家人都很满意。”陈奕说。 10月1日，在上…",
    "content": "新华社上海10月6日电（记者陈爱平）这个国庆节假期，上海白领郑冰的安排既充实又从容。她和朋友们在中秋节假期出发、前往马来西亚海边潜水、冲浪，国庆节假期后半段回到上海后，她们打卡了徐汇西岸融合网球与音乐的“ACE汇师”城市主题活动，又到辰山植物园露营放松。 重庆游客陈奕一家前往法国、西班牙自由行，他们整个行程有13天，在巴黎、巴塞罗那专门留出了充裕时间去逛博物馆、公园等。“此次安排舒缓而有深度，一家人都很满意。”陈奕说。 10月1日，在上海市徐汇区西岸梦中心举行的“ACE汇师”城市主题活动现场。新华社记者 陈爱平 摄…"
