    "description": "为保障国庆假期高速公路大型车辆道路交通安全，防范疲劳驾驶引发的交通事故，深圳交警以“长途运输忙，喝口水吃颗糖，平安记心上”为主题，通过“一瓶水、两颗糖、三句温馨话”的“123”暖心工作法，开展大货车、大客车交通安全警示教育与服务工作，为群众假期出行筑牢道路交通安全屏障。 记者：毛思倩 视频来源：深圳交警 新华社音视频部制作",
    "content": "为保障国庆假期高速公路大型车辆道路交通安全，防范疲劳驾驶引发的交通事故，深圳交警以“长途运输忙，喝口水吃颗糖，平安记心上”为主题，通过“一瓶水、两颗糖、三句温馨话”的“123”暖心工作法，开展大货车、大客车交通安全警示教育与服务工作，为群众假期出行筑牢道路交通安全屏障。 记者：毛思倩 视频来源：深圳交警 新华社音视频部制作"
