    "author": "陈玉芬,王作葵",
    "description": "新华社里加10月6日电（记者陈玉芬）维尔纽斯消息：立陶宛议会6日就一项旨在解禁本国部署核武器的宪法修正案举行首轮表决，支持废除宪法中的相关禁令。这为日后允许包括核武器在内的大规模杀伤性武器进入或部署在立陶宛境内迈出第一步。 根据立陶宛议会公布的信息，这项宪法修正案内容是废除宪法第137条。宪法第137条规定，立陶宛境内不得存在大规模杀伤性武器和外国军事基地。这一条款实际上禁止了核武器进入或部署在立陶宛。 立陶宛议会此前就修宪案作出说明时…",
    "content": "新华社里加10月6日电（记者陈玉芬）维尔纽斯消息：立陶宛议会6日就一项旨在解禁本国部署核武器的宪法修正案举行首轮表决，支持废除宪法中的相关禁令。这为日后允许包括核武器在内的大规模杀伤性武器进入或部署在立陶宛境内迈出第一步。 根据立陶宛议会公布的信息，这项宪法修正案内容是废除宪法第137条。宪法第137条规定，立陶宛境内不得存在大规模杀伤性武器和外国军事基地。这一条款实际上禁止了核武器进入或部署在立陶宛。 立陶宛议会此前就修宪案作出说明时表示，废除这一条款的目的是解除立陶宛全面参与北约集体防御和威慑体系的限制。 立陶…"
