    "content": "新华社巴黎10月6日电（记者乔本孝）法国总统马克龙6日在社交媒体发文说，法国一艘战略核潜艇当日成功试射一枚M51.3潜射洲际导弹。 马克龙说，这是该型号导弹首次试射，本次试射成功对外发出了法国具备实力的清晰信号。 据法国媒体援引法国总统府及国防部消息报道，法军战略核潜艇6日在该国菲尼斯泰尔省海域试射一枚未装载核弹头的M51.3导弹，导弹落入北大西洋海域。 法国是欧盟唯一拥有核武器的国家。今年3月，马克龙就法国核威慑政策发表讲话时提出“前沿威慑”计划。该计划为伙伴国提供参与核威慑演习的机会，在某些情况下能让法国“在盟…"
